const items = $input.all();
const valid = [];
const invalid = [];

for (const item of items) {
  const data = item.json;
  if (!data.ticket_id || !data.message || !data.product) {
    invalid.push({
      json: {
        ticket_id: data.ticket_id || null,
        execution_status: 'Failed',
        error_message: 'Missing required fields (ticket_id, message, or product)',
        timestamp: new Date().toISOString()
      }
    });
  } else {
    let email = (data.customer_email || '').trim().toLowerCase();
    if (email.endsWith('@gmail.com')) {
      const [local, domain] = email.split('@');
      const cleanLocal = local.split('+')[0];
      email = `${cleanLocal}@${domain}`;
    }
    data.customer_email_normalized = email;
    valid.push({ json: data });
  }
}

return [
  valid,
  invalid
];

const item = $input.item.json;
const subs = item.subscriptions || [];
const matchingSubs = subs.filter(s => s.product === item.product);
const activeSubs = matchingSubs.filter(s => s.status === 'active');

let status = 'not_executed';
let reason = null;

if (activeSubs.length === 1) {
  status = 'simulated_success';
} else if (activeSubs.length > 1) {
  status = 'requires_review';
  reason = 'Multiple active subscriptions found';
} else {
  status = 'not_executed';
  reason = 'No active matching subscription found';
}

return {
  json: {
    ...item,
    matching_subscription_count: matchingSubs.length,
    action_type: 'cancellation',
    action_status: status,
    details: { reason }
  }
};

const item = $input.item.json;
const subs = item.subscriptions || [];
const matchingSubs = subs.filter(s => s.product === item.product);
const activeSubs = matchingSubs.filter(s => s.status === 'active');

let status = 'not_executed';
let reason = null;
const provider = activeSubs.length > 0 ? activeSubs[0].billing_provider : (matchingSubs[0]?.billing_provider || 'unknown');

if (activeSubs.length === 1) {
  status = 'simulated_success';
} else if (activeSubs.length > 1) {
  status = 'requires_review';
  reason = 'Multiple active subscriptions found';
} else {
  status = 'not_executed';
  reason = 'No active matching subscription found';
}

return {
  json: {
    ...item,
    matching_subscription_count: matchingSubs.length,
    action_type: 'cancellation_with_billing_clarification',
    action_status: status,
    billing_provider: provider,
    details: { reason, billing_provider: provider }
  }
};

const item = $input.item.json;
const subs = item.subscriptions || [];
const matchingSubs = subs.filter(s => s.product === item.product);

let status = 'not_executed';
let reason = null;

if (matchingSubs.length >= 1) {
  status = 'simulated_success';
} else {
  status = 'not_executed';
  reason = 'No matching subscription for product';
}

return {
  json: {
    ...item,
    matching_subscription_count: matchingSubs.length,
    action_type: 'refund',
    action_status: status,
    details: { reason }
  }
};

const item = $input.item.json;
const kb = [
  { topic: 'freezing', response_context: 'Ask the customer to update the app, restart the device, and retry.' },
  { topic: 'login', response_context: 'Ask the customer to verify the account email and reset the password.' }
];

const msg = (item.message || '').toLowerCase();
const matchedKb = kb.find(k => msg.includes(k.topic));

let status = 'simulated_success';
let reason = null;
let context = null;

if (matchedKb) {
  context = matchedKb.response_context;
} else {
  status = 'requires_review';
  reason = 'No matching knowledge base troubleshooting topic found';
}

return {
  json: {
    ...item,
    matching_subscription_count: (item.subscriptions || []).filter(s => s.product === item.product).length,
    action_type: 'technical_issue',
    action_status: status,
    troubleshooting_context: context,
    details: { reason, troubleshooting_context: context }
  }
};

const item = $input.item.json;
return {
  json: {
    ...item,
    matching_subscription_count: (item.subscriptions || []).filter(s => s.product === item.product).length,
    action_type: 'other',
    action_status: 'queued',
    details: { reason: 'General inquiry queued for manual support review' }
  }
};

const item = $input.item.json;
return {
  json: {
    timestamp: new Date().toISOString(),
    ticket_id: item.ticket_id,
    detected_intent: item.action_type,
    matching_subscription_count: item.matching_subscription_count,
    action_type: item.action_type,
    action_status: item.action_status,
    execution_status: 'Success',
    error_message: null,
    generated_response: item.generated_response || null
  }
};
